> sgtm, are you thinking of something specific for volume controllers, or something in the sharedinformer interface? If the latter, we'll have to run this by sig-apimachinery

I'm thinking of the former, as this indexer is controller-specific. Here is pseudocode:

``` go
const (
     // PodPVCIndex is the lookup name for the index function, which is to index by pod pvcs.
     PodPVCIndex = "pod-pvc-index" 
)

// PodPVCIndexFunc returns PVC keys for given pod
func PodPVCIndexFunc(obj interface{}) ([]string, error) {
    pod, ok := obj.(*v1.Pod)
    if !ok {
        return []string{}, nil 
    }    
    keys := []string{}
    for _, podVolume := range pod.Spec.Volumes {
        if pvcSource := podVolume.VolumeSource.PersistentVolumeClaim; pvcSource != nil {
            keys = append(keys, fmt.Sprintf("%s/%s", pod.Namespace, pvcSource.ClaimName))
        }   
    }   
    return keys, nil
}

func AddIndexerIfNotPresent(indexer cache.Indexer, indexName string, indexFunc cache.IndexFunc) error {
     indexers := indexer.GetIndexers()
     if _, ok := indexers[indexName]; ok {
         return nil
     }
     return indexer.AddIndexers(cache.Indexers{indexName: indexFunc})
}
```

In each controller, we use the following code to initialize pod indexer:

```go
controller.podIndexer = p.PodInformer.Informer().GetIndexer()
if err := AddIndexerIfNotPresent(controller.podIndexer, PodPVCIndex, PodPVCIndexFunc); err != nil {
     return err
}

// now, this controller can use `PodPVCIndex` lookup name to access this shared indexer.
```

- the controller initialization order does not matter
- and controllers can be enabled/disabled independently
